// Define a function to sample a direction from a distribution (e.g. Lambertian, specular)
sampleDirection(distribution, direction) = {
  // Sample a random direction from the distribution
  newDirection.x = distribution.sampleX()
  newDirection.y = distribution.sampleY()
  newDirection.z = distribution.sampleZ()

  // Ensure the direction is within the hemisphere
  if (newDirection.z < 0) newDirection.z = -sqrt(1 - newDirection.x^2 - newDirection.y^2)

  return newDirection
}

// Define a function to evaluate the importance sampling weight for a given direction
importanceSamplingWeight(direction) = {
