  lightDirection = sampleDirection(lightDistribution, initialCameraPosition)

  // Sample a random direction from the viewport distribution
  viewportDirection = sampleDirection(viewportDistribution, initialCameraPosition)

  // Calculate the importance sampling weight for the light direction
  lightWeight = importanceSamplingWeight(lightDirection)

  // Calculate the importance sampling weight for the viewport direction
