    this.zoom = 1;
    this Branches = [];
    this.Radius = 0.7;
    this.Thickness = 0.05;
  }

  render() {
    translate(width/2, height/2);
    rotateY(this.angle);
    rotateX(this.angle);
    stroke(255, 0, 0);
    strokeWeight(this.Thickness);
    for (let i = 0; i < 1000; i++) {
      this.Radius *= 0.95;
      this.Thickness *= 0.95;
      let h = map(sin(this.angle), -1, 1, 0, TWO_PI);
      let r = this.Radius * sin(h);
      let z = this.Radius * cos(h);
      beginShape();
      vertex(0, 0, 0);
      vertex(r * cos(i * TWO_PI / 1000), r * sin(i * TWO_PI / 1000), z);
      endShape();
    }
    this.angle += 0.01;
  }
}
```

