      <input
        type="text"
        value={inputValue}
        onChange={handleInputChange}
        placeholder="Type to search..."
      />
      {filteredOptions.map((option, index) => (
        <div
          key={index}
          className={activeOption === option ? 'active' : ''}
          onClick={() => handleClick(option)}
        >
          {option}
        </div>
      ))}
    </div>
  );
};

export default Autocomplete;
